int linear_search(const int values[], int size, int target) {
    for (int i = 0; i < size; i++) {
        if (values[i] == target) {
            return i;
        }
    }
    return -1;
}

int binary_search(const int values[], int size, int target) {
    int low = 0;
    int high = size - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (values[mid] == target) {
            return mid;
        }
        if (values[mid] < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return -1;
}

void bubble_sort(int values[], int size) {
    for (int pass = 0; pass < size - 1; pass++) {
        for (int i = 0; i < size - 1 - pass; i++) {
            if (values[i] > values[i + 1]) {
                int temp = values[i];
                values[i] = values[i + 1];
                values[i + 1] = temp;
            }
        }
    }
}

void selection_sort(int values[], int size) {
    for (int i = 0; i < size - 1; i++) {
        int smallest = i;
        for (int j = i + 1; j < size; j++) {
            if (values[j] < values[smallest]) {
                smallest = j;
            }
        }
        if (smallest != i) {
            int temp = values[i];
            values[i] = values[smallest];
            values[smallest] = temp;
        }
    }
}

void insertion_sort(int values[], int size) {
    for (int i = 1; i < size; i++) {
        int key = values[i];
        int j = i - 1;
        while (j >= 0 && values[j] > key) {
            values[j + 1] = values[j];
            j--;
        }
        values[j + 1] = key;
    }
}

static int merge(int values[], int left, int mid, int right) {
    int size = right - left + 1;
    int *merged = malloc(size * sizeof(int));
    if (merged == NULL) {
        return -1;
    }
    int i = left;
    int j = mid + 1;
    int k = 0;
    while (i <= mid && j <= right) {
        if (values[i] <= values[j]) {
            merged[k++] = values[i++];
        } else {
            merged[k++] = values[j++];
        }
    }
    while (i <= mid) {
        merged[k++] = values[i++];
    }
    while (j <= right) {
        merged[k++] = values[j++];
    }
    for (k = 0; k < size; k++) {
        values[left + k] = merged[k];
    }
    free(merged);
    return 0;
}

int merge_sort(int values[], int left, int right) {
    if (left >= right) {
        return 0;
    }
    int mid = left + (right - left) / 2;
    if (merge_sort(values, left, mid) != 0) {
        return -1;
    }
    if (merge_sort(values, mid + 1, right) != 0) {
        return -1;
    }
    return merge(values, left, mid, right);
}

static void swap_values(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

static int partition(int values[], int low, int high) {
    int pivot = values[high];
    int i = low - 1;
    for (int j = low; j < high; j++) {
        if (values[j] <= pivot) {
            i++;
            swap_values(&values[i], &values[j]);
        }
    }
    swap_values(&values[i + 1], &values[high]);
    return i + 1;
}

void quick_sort(int values[], int low, int high) {
    if (low >= high) {
        return;
    }
    int pivot = partition(values, low, high);
    quick_sort(values, low, pivot - 1);
    quick_sort(values, pivot + 1, high);
}

static void sift_down(int values[], int size, int root) {
    while (2 * root + 1 < size) {
        int child = 2 * root + 1;
        if (child + 1 < size && values[child + 1] > values[child]) {
            child++;
        }
        if (values[root] >= values[child]) {
            return;
        }
        int temp = values[root];
        values[root] = values[child];
        values[child] = temp;
        root = child;
    }
}

void heap_sort(int values[], int size) {
    for (int start = size / 2 - 1; start >= 0; start--) {
        sift_down(values, size, start);
    }
    for (int end = size - 1; end > 0; end--) {
        int temp = values[0];
        values[0] = values[end];
        values[end] = temp;
        sift_down(values, end, 0);
    }
}

