    int adjacency[MAX_VERTICES][MAX_VERTICES];
} Graph;

void graph_init(Graph *graph, int num_vertices) {
    graph->num_vertices = num_vertices;
    for (int i = 0; i < num_vertices; i++) {
        for (int j = 0; j < num_vertices; j++) {
            graph->adjacency[i][j] = 0;
        }
    }
}

void graph_add_edge(Graph *graph, int from, int to, int weight) {
    graph->adjacency[from][to] = weight;
    graph->adjacency[to][from] = weight;
}

void breadth_first_search(const Graph *graph, int start, int visited[]) {
    int queue[MAX_VERTICES];
    int head = 0;
    int tail = 0;
    for (int i = 0; i < graph->num_vertices; i++) {
        visited[i] = 0;
    }
    visited[start] = 1;
    queue[tail++] = start;
    while (head < tail) {
        int vertex = queue[head++];
        printf("%d ", vertex);
        for (int next = 0; next < graph->num_vertices; next++) {
            if (graph->adjacency[vertex][next] != 0 && visited[next] == 0) {
                visited[next] = 1;
                queue[tail++] = next;
            }
        }
    }
}

static void depth_first_visit(const Graph *graph, int vertex, int visited[]) {
    visited[vertex] = 1;
    printf("%d ", vertex);
    for (int next = 0; next < graph->num_vertices; next++) {
        if (graph->adjacency[vertex][next] != 0 && visited[next] == 0) {
            depth_first_visit(graph, next, visited);
        }
    }
}

void depth_first_search(const Graph *graph, int start, int visited[]) {
    for (int i = 0; i < graph->num_vertices; i++) {
        visited[i] = 0;
    }
    depth_first_visit(graph, start, visited);
}

void dijkstra(const Graph *graph, int start, int distances[]) {
    int visited[MAX_VERTICES] = {0};
    for (int i = 0; i < graph->num_vertices; i++) {
        distances[i] = INT_MAX;
    }
    distances[start] = 0;
    for (int step = 0; step < graph->num_vertices; step++) {
        int current = -1;
        for (int i = 0; i < graph->num_vertices; i++) {
            if (!visited[i] && (current == -1 || distances[i] < distances[current])) {
                current = i;
            }
        }
        if (current == -1 || distances[current] == INT_MAX) {
            break;
        }
        visited[current] = 1;
        for (int next = 0; next < graph->num_vertices; next++) {
            int weight = graph->adjacency[current][next];
            if (weight != 0 && distances[current] <= INT_MAX - weight &&
                distances[current] + weight < distances[next]) {
                distances[next] = distances[current] + weight;
            }
        }
    }
}

